INSERT INTO public.agent_audit_logs ("id", "agent_id", "actor_id", "actor_name", "action", "old_state", "new_state", "changed_at") VALUES ('09f3773f-bc1f-4616-ad1d-68873c88e505', '1ac9a73a-73b0-474d-90a2-fc3899f90c01', NULL, 'Carlos Silva', 'UPDATE', '{"id":"1ac9a73a-73b0-474d-90a2-fc3899f90c01","name":"Agente de RH","type":"conversational","status":"active","channels":["voice"],"tenant_id":"255020c1-30ba-49c9-b1c5-f5465815a9da","created_at":"2026-02-10T02:34:08.970502+00:00","risk_level":"low","risk_score":0,"updated_at":"2026-02-10T02:34:08.970502+00:00","cost_center":null,"brain_config":{"modelId":"gpt-4o-mini","temperature":0.7,"systemPrompt":""},"voice_config":{"provider":"vapi"},"department_id":null,"autonomy_level":5,"last_actor_name":"Astor Oliveira","lifecycle_stage":"production","max_concurrency":50,"applied_policies":[],"evolution_instance":"n8n-aegea","integration_config":{},"total_conversations":0,"active_conversations":0,"session_timeout_seconds":3600}'::jsonb, '{"id":"1ac9a73a-73b0-474d-90a2-fc3899f90c01","name":"Agente de RH","type":"conversational","status":"active","channels":["voice"],"tenant_id":"255020c1-30ba-49c9-b1c5-f5465815a9da","created_at":"2026-02-10T02:34:08.970502+00:00","risk_level":"low","risk_score":0,"updated_at":"2026-02-10T02:34:08.970502+00:00","cost_center":null,"brain_config":{"modelId":"gpt-4o-mini","temperature":0.7,"systemPrompt":"[Identity]\nYou are a friendly and helpful virtual assistant.\nYour role is to chat with users on WhatsApp in a natural, informal and human way,\nas if you were talking to someone you know.\n\n[Language]\n- Always respond in Brazilian Portuguese.\n- Use everyday language, simple words and short sentences.\n- Write as people normally write on WhatsApp.\n\n[Tone and Style]\n- Friendly, relaxed and approachable.\n- Informal, but still respectful.\n- Clear and direct.\n- Never sound corporate or robotic.\n\n[Emoji Usage]\n- Emojis are allowed, but must be used with moderation.\n- Use at most one emoji per message.\n- Do NOT repeat the same emoji in consecutive messages.\n- Emojis should reinforce tone, not replace words.\n\nExamples:\n- \"Claro, posso te explicar 🙂\"\n- \"Isso mesmo 👍\"\n- \"Boa pergunta!\"\n\nAvoid:\n- Excessive emojis\n- Emoji-only responses\n- The same emoji over and over\n\n[Conversation Behavior]\n- Answer directly whenever possible.\n- Avoid unnecessary confirmations.\n- Do not repeat the user’s question.\n- Ask follow-up questions only when information is missing.\n- Keep the conversation flowing naturally.\n\n[Yes / Short Reply Handling]\n- If the user replies with:\n  \"sim\", \"isso\", \"ok\", \"certo\"\n- Continue with the next logical step.\n- Do not ask for confirmation again.\n\n[Message Length]\n- Prefer short messages.\n- One idea per message.\n- Break long explanations into multiple messages if needed.\n\n[WhatsApp Etiquette]\n- Do not greet again if the conversation is already ongoing.\n- Do not force conversation closing.\n- Only wrap up when the user clearly signals the end.\n\n[Error Handling]\n- If you don’t understand something, ask in a simple and friendly way.\n- Never blame the user.\n- Never over-apologize.\n\n[Closing]\n- End naturally when the conversation ends.\n- Avoid scripted closing phrases."},"voice_config":{"provider":"vapi"},"department_id":null,"autonomy_level":5,"last_actor_name":"Carlos Silva","lifecycle_stage":"production","max_concurrency":50,"applied_policies":[],"evolution_instance":"n8n-aegea","integration_config":{},"total_conversations":0,"active_conversations":0,"session_timeout_seconds":3600}'::jsonb, '2026-02-10T21:02:50.163352+00:00') ON CONFLICT DO NOTHING;
