INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (349, 'dNYvHXlfMfCcqA7x3EB0151B6CB6C8B983AE65', '{"name":"Answer_questions_with_a_vector_store","type":"tool","content":"[{\"response\":\"Para ser contratado, geralmente você precisa entregar os seguintes documentos:\\n\\n1. Documento de identificação com foto (RG, CNH, Passaporte)\\n2. CPF\\n3. Carteira de Trabalho (CTPS)\\n4. Certificado de Reservista (para homens)\\n5. Título de eleitor e comprovante de votação ou certidão de quitação eleitoral\\n6. Comprovante de endereço\\n7. Certificados ou diplomas acadêmicos/curso (se aplicável)\\n8. Carteira de vacinação (se solicitado)\\n9. Foto 3x4 (se solicitado)\\n\\nComo seu pedido está relacionado ao contexto da Aegea, recomendo verificar sua comunicação oficial com a empresa, pois podem solicitar documentos específicos. Se precisar, posso verificar detalhes no documento de onboarding da Aegea para confirmar se há alguma exigência específica informada. Deseja que eu faça isso?\"}]","tool_call_id":"call_RSCauIPEBltOJjlq2qwrxLdX","additional_kwargs":{},"response_metadata":{}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (350, 'dNYvHXlfMfCcqA7x3EB0151B6CB6C8B983AE65', '{"type":"ai","content":"Para ser contratado, você geralmente precisa entregar os seguintes documentos:\n\n1. Documento de identificação com foto (RG, CNH, Passaporte)\n2. CPF\n3. Carteira de Trabalho (CTPS)\n4. Certificado de Reservista (para homens)\n5. Título de eleitor e comprovante de votação ou certidão de quitação eleitoral\n6. Comprovante de endereço\n7. Certificados ou diplomas acadêmicos/curso (se aplicável)\n8. Carteira de vacinação (se solicitado)\n9. Foto 3x4 (se solicitado)\n\nComo você está lidando com a Aegea, pode haver documentos específicos que eles pedem. Quer que eu verifique se há alguma exigência adicional no onboarding deles?","tool_calls":[],"additional_kwargs":{},"response_metadata":{},"invalid_tool_calls":[]}'::jsonb) ON CONFLICT DO NOTHING;
