INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (353, 'dNYvHXlfMfCcqA7x3EB082E294F7CDE7269F8F', '{"name":"Answer_questions_with_a_vector_store","type":"tool","content":"[{\"response\":\"Para fazer o exame admissional, você deve seguir os procedimentos determinados pela empresa, que geralmente incluem agendamento do exame com o serviço médico contratado pela organização. O exame admissional é realizado antes do início das suas atividades laborais para avaliar sua aptidão física e mental para o cargo.\\n\\nRecomendo que você entre em contato com o setor de Recursos Humanos (RH) da sua empresa para solicitar informações sobre onde e quando o exame será realizado, além dos documentos necessários para o atendimento. Eles poderão orientá-lo sobre os locais credenciados e os horários disponíveis.\\n\\nSe precisar de informações mais específicas sobre o procedimento conforme a empresa Aegea, posso verificar no material disponível. Você deseja?\"}]","tool_call_id":"call_Qk4aDpWHLJmkajCn2EBcrjAo","additional_kwargs":{},"response_metadata":{}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (354, 'dNYvHXlfMfCcqA7x3EB082E294F7CDE7269F8F', '{"type":"ai","content":"Para fazer o exame admissional, você precisa seguir os procedimentos da empresa. Normalmente, isso envolve agendar o exame com o serviço médico que a empresa contrata. O exame é para avaliar sua aptidão para o cargo.\n\nÉ bom você entrar em contato com o setor de Recursos Humanos (RH) da empresa. Eles vão te dar detalhes sobre onde e quando o exame será feito e quais documentos você precisa levar.\n\nSe precisar de informações específicas sobre a empresa Aegea, posso verificar. Você gostaria disso?","tool_calls":[],"additional_kwargs":{},"response_metadata":{},"invalid_tool_calls":[]}'::jsonb) ON CONFLICT DO NOTHING;
