INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (386, 'dNYvHXlfMfCcqA7x3EB0DA99C4AF021A20AAE8', '{"type":"ai","content":"{\n  \"content\": \"Você pode enviar o documento de união estável, sim. Ele é aceito como comprovação de vínculo. \\n\\nLembre-se de que é importante que todos os documentos estejam em conformidade para facilitar o processo. Caso tenha mais alguma dúvida, estou aqui para ajudar!\"\n}","tool_calls":[],"additional_kwargs":{},"response_metadata":{},"invalid_tool_calls":[]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (387, 'dNYvHXlfMfCcqA7x2A584E69301F5EF18857', '{"type":"human","content":"Contexto da conversa:\n\nNome informado pelo cliente: Davos\nTelefone informado pelo cliente: 6872081948855\nData atual: 2026-02-11T19:23:33.877-03:00\nMensagem do cliente: Olá boa tarde. Claro Katia, qual ajuda você precisa?\n\nVocê está conversando com um colaborador ou candidato via WhatsApp\nsobre onboarding e assuntos de Recursos Humanos da Aegea.\n\nINSTRUÇÕES DE RESPOSTA:\n\n1. Use sempre o contexto da conversa.\n   - Não repita perguntas já respondidas.\n   - Não peça novamente informações já confirmadas.\n\n2. Se a pergunta for direta e clara,\n   responda diretamente usando exclusivamente\n   as informações da base oficial de onboarding da Aegea.\n\n3. Se a pergunta envolver:\n   - lista de documentos\n   - benefícios\n   - plano de saúde\n   - salário\n   - exame admissional\n   você deve reproduzir exatamente o que está na base oficial,\n   sem resumir ou modificar.\n\n4. Se a informação solicitada não estiver explicitamente na base oficial:\n   - informe que essa informação deve ser confirmada com o RH.\n   - não invente.\n   - não generalize.\n\n5. Se o cliente perguntar sobre envio de documentos:\n   - confirme apenas os canais definidos oficialmente.\n   - nunca assuma que WhatsApp é canal válido,\n     a menos que esteja explicitamente definido.\n\n6. Após responder:\n   - opcionalmente acrescente uma breve orientação útil,\n     sem pressionar e sem encerrar de forma genérica.\n\n7. Se o cliente perguntar sobre identidade da empresa ou setor,\n   responda com as informações oficiais da empresa representada.\n   Nunca use placeholders ou descrições genéricas.\n\nOBJETIVO DA RESPOSTA:\n\nFornecer informações corretas, seguras e oficiais\nsobre o onboarding da Aegea,\nmantendo clareza e profissionalismo.","additional_kwargs":{},"response_metadata":{}}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.chat_histories_memory ("id", "session_id", "message") VALUES (388, 'dNYvHXlfMfCcqA7x2A584E69301F5EF18857', '{"type":"ai","content":"{\n  \"content\": \"Olá Davos! Você está falando com a Aegea. Como posso ajudar você hoje com relação ao processo de onboarding ou assuntos de Recursos Humanos?\"\n}","tool_calls":[],"additional_kwargs":{},"response_metadata":{},"invalid_tool_calls":[]}'::jsonb) ON CONFLICT DO NOTHING;
